// ABK Card Game — servidor mobile e multiplayer, pacote único para GitHub + Render.
// Descompacta os recursos do jogo em pasta temporária e inicia o servidor Node.js.
// Sem npm install, banco de dados externo ou dependências de terceiros.
'use strict';
const fs=require('node:fs');
const os=require('node:os');
const path=require('node:path');
const zlib=require('node:zlib');
const packed='';
const payload=JSON.parse(zlib.gunzipSync(Buffer.from(packed,'base64')).toString('utf8'));
const base=fs.mkdtempSync(path.join(os.tmpdir(),'abk-card-game-'));
for(const [file,data] of Object.entries(payload)) {
  const out=path.join(base,file);
  fs.mkdirSync(path.dirname(out),{recursive:true});
  fs.writeFileSync(out,Buffer.from(data,'base64'));
}
console.log('[ABK] Inicializando Card Game: mobile, 160 cartas, multiplayer 2–4 jogadores.');
require(path.join(base,'server.js'));
